"import os
import math

def write_file(path, content):
    # Ensure directory exists
    dirname = os.path.dirname(path)
    if dirname:
        os.makedirs(dirname, exist_ok=True)

    with open(path, 'w') as f:
        f.write(content)

# --- Constants ---
nx, ny, nz = 20, 20, 1
lx, ly, lz = 1.0, 1.0, 0.1
dx, dy = lx/nx, ly/ny

# --- 0/z (Bed Level) ---
# Generating a nonuniform list for the square bump
# Bump center: (0.5, 0.5), size: 0.2x0.2 (from 0.4 to 0.6), height: 0.02
z_values = []
for k in range(nz):
    for j in range(ny):
        for i in range(nx):
            cx = (i + 0.5) * dx
            cy = (j + 0.5) * dy
            # Square bump logic
            if 0.4 < cx < 0.6 and 0.4 < cy < 0.6:
                z_values.append("0.02")
            else:
                z_values.append("0.0")

z_internal = "\n".join(z_values)
z_count = len(z_values)

